// C4 rank property suite (f91). SYNTHETIC DATA ONLY: every job below is generated by a fixed-seed PRNG, none is real.
// The real rankFor is checked against 2,000 generated job histories per invariant, and a switchable reference model
// (proved equal to the real function on all histories) is mutated 7 ways to prove the invariants bite.
import { test } from "node:test";
import assert from "node:assert/strict";
import { rankFor, boardOrder, WEIGHT, TIERS, type Rank } from "../src/market/rank.ts";
import { washTradeFlags } from "../src/market/attribution.ts";
import { leaderboard } from "../src/market/service.ts";
import { MemoryMarketStore, type Job, type JobStatus } from "../src/market/store.ts";

const N = 2000, SEED = 0xC4F91;
const PRO = "pro_main";
function prng(seed: number) { let a = seed >>> 0; return () => { a = (a + 0x6D2B79F5) >>> 0; let t = a; t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }; }
type R = () => number;
const pick = <T,>(r: R, xs: readonly T[]): T => xs[Math.floor(r() * xs.length)];
const STATUSES: JobStatus[] = ["awaiting_funds", "open", "claimed", "delivered", "reproved", "paid", "disputed", "cancelled", "refunded"];
let uid = 0;
function job(r: R, o: Partial<Job> = {}): Job {
  const id = `syn_${uid++}`;
  return { id, ownerAccountId: `own_${id}`, domainId: `d_${id}`, domain: `${id}.example.test`, check: "SPF", severity: pick(r, ["FAIL", "WARN"] as const), tier: "small",
    priceCents: 1000, claimFeeCents: 100, status: "paid", createdAt: 1000 + Math.floor(r() * 1e6), updatedAt: 0, baseline: { at: 0, status: "WARN", detail: "syn" },
    proAccountId: PRO, abandonedBy: [], rescans: 1, proof: { scanId: `s_${id}`, at: 5000, baseline: "WARN", now: "PASS", detail: "syn" },
    payerFp: `fp_${id}`, ownerEmailDomain: `${id}.owner.test`, proEmailDomain: "pro.example.test", warrantyChecks: 0, events: [], ...o };
}
/** A clean, ranked-eligible job: proven, paid or reproved, unlinked payer and email, not self-dealt. Optionally regressed. */
const clean = (r: R): Job => job(r, { status: pick(r, ["paid", "reproved"] as const), regressedAt: r() < 0.3 ? 9000 : undefined });
/** A job that must NEVER add rank, in one of four ways. */
function poison(r: R, kind: string): Job {
  switch (kind) {
    case "unproven": return job(r, { proof: undefined, status: pick(r, ["claimed", "delivered", "paid"] as const) });
    case "refunded": return job(r, { status: pick(r, ["refunded", "cancelled", "disputed"] as const) });
    case "wash_card": { const j = job(r); return { ...j, proPayerFp: j.payerFp }; }                       // pro paid with the owner's card
    case "wash_domain": return job(r, { ownerEmailDomain: "shared-firm.test", proEmailDomain: "shared-firm.test" });   // pair sharing an org domain, repeats flag both
    case "self_dealt": { const j = job(r); return { ...j, ownerAccountId: PRO }; }
    default: throw new Error(kind);
  }
}
const KINDS = ["unproven", "refunded", "wash_card", "self_dealt"] as const;
const history = (r: R, max = 25): Job[] => { const out: Job[] = []; const n = Math.floor(r() * max); for (let i = 0; i < n; i++) { const x = r(); out.push(x < 0.55 ? clean(r) : x < 0.7 ? job(r, { proAccountId: "pro_other" }) : poison(r, pick(r, KINDS))); } return out; };
function shuffle<T>(r: R, xs: T[]): T[] { const a = [...xs]; for (let i = a.length - 1; i > 0; i--) { const k = Math.floor(r() * (i + 1)); [a[i], a[k]] = [a[k], a[i]]; } return a; }

type RankFn = (pro: string, jobs: Job[]) => Rank;
// ---- reference model with mutation switches (mutant = one switch on) ----
interface Mut { countUnproven?: boolean; countRefunded?: boolean; ignoreWash?: boolean; orderDependent?: boolean; allowSelfDealt?: boolean }
function model(m: Mut = {}): RankFn {
  return (pro, jobs) => {
    let points = 0, proven = 0, regressed = 0, holding = 0, abandoned = 0, washExcluded = 0;
    const wash = washTradeFlags(jobs);
    for (const j of jobs) {
      if (j.abandonedBy.includes(pro)) abandoned++;
      if (j.proAccountId !== pro) continue;
      if (!m.countUnproven && !j.proof) continue;
      if (!m.countRefunded && !(j.status === "paid" || j.status === "reproved")) continue;
      if (m.countRefunded && !["paid", "reproved", "refunded", "cancelled", "disputed"].includes(j.status)) continue;
      if (!m.ignoreWash && wash.has(j.id)) { washExcluded++; continue; }
      if (!m.allowSelfDealt && j.ownerAccountId === pro) { washExcluded++; continue; }
      proven++;
      if (j.regressedAt) { regressed++; if (m.orderDependent) break; continue; }   // mutant: a regression ends the scan, so event order changes the total
      holding++; points += WEIGHT[j.severity];
    }
    const tier = TIERS.find((t) => points >= t.min)?.name ?? "Unranked";
    return { points, tier, provenFixes: proven, holding, regressed, abandoned, washExcluded, holdRate: proven ? Math.round((holding / proven) * 1000) / 10 : null, note: "" };
  };
}
const num = (r: Rank) => [r.points, r.provenFixes, r.holding, r.regressed, r.washExcluded, r.abandoned];
const strip = (r: Rank) => ({ ...r, note: "" });

// ---- the invariants, each returns how many generated cases it passed (throws on the first failure) ----
type Inv = (rank: RankFn) => number;
const INVARIANTS: Record<string, Inv> = {
  deterministic: (rank) => { const r = prng(SEED + 1); for (let i = 0; i < N; i++) { const h = history(r); assert.deepEqual(rank(PRO, h), rank(PRO, structuredClone(h)), `case ${i}`); assert.deepEqual(rank(PRO, h), rank(PRO, h)); } return N; },
  noScoreFromUnproven: (rank) => { const r = prng(SEED + 2); for (let i = 0; i < N; i++) { const h = history(r); const base = rank(PRO, h); const after = rank(PRO, [...h, poison(r, "unproven")]); assert.equal(after.points, base.points, `case ${i}`); assert.equal(after.provenFixes, base.provenFixes, `case ${i}`); } return N; },
  noScoreFromRefunded: (rank) => { const r = prng(SEED + 3); for (let i = 0; i < N; i++) { const h = history(r); const base = rank(PRO, h); const after = rank(PRO, [...h, poison(r, "refunded")]); assert.equal(after.points, base.points, `case ${i}`); assert.equal(after.provenFixes, base.provenFixes, `case ${i}`); } return N; },
  noScoreFromWash: (rank) => { const r = prng(SEED + 4); for (let i = 0; i < N; i++) { const h = history(r); const base = rank(PRO, h); const w = r() < 0.5 ? poison(r, "wash_card") : (() => { const a = poison(r, "wash_domain"), b = poison(r, "wash_domain"); return [a, b]; })(); const ws = Array.isArray(w) ? w : [w]; const after = rank(PRO, [...h, ...ws]); assert.ok(after.points <= base.points, `case ${i}: wash raised points`); assert.ok(after.provenFixes <= base.provenFixes, `case ${i}`); } return N; },
  noScoreFromSelfDealt: (rank) => { const r = prng(SEED + 5); for (let i = 0; i < N; i++) { const h = history(r); const base = rank(PRO, h); const after = rank(PRO, [...h, poison(r, "self_dealt")]); assert.equal(after.points, base.points, `case ${i}`); assert.equal(after.provenFixes, base.provenFixes, `case ${i}`); } return N; },
  monotoneInProven: (rank) => { const r = prng(SEED + 6); for (let i = 0; i < N; i++) { let h = history(r, 12); let prev = rank(PRO, h); for (let k = 0; k < 4; k++) { h = [...h, clean(r)]; const now = rank(PRO, h); assert.ok(now.points >= prev.points && now.provenFixes === prev.provenFixes + 1, `case ${i}.${k}: ${prev.points}->${now.points}`); prev = now; } } return N; },
  orderIndependent: (rank) => { const r = prng(SEED + 7); for (let i = 0; i < N; i++) { const h = history(r); assert.deepEqual(rank(PRO, shuffle(r, h)), rank(PRO, h), `case ${i}`); assert.deepEqual(rank(PRO, [...h].reverse()), rank(PRO, h), `case ${i} rev`); } return N; },
  wellFormed: (rank) => { const r = prng(SEED + 8); for (let i = 0; i < N; i++) { const x = rank(PRO, history(r, 40)); for (const v of num(x)) assert.ok(Number.isFinite(v) && v >= 0 && Number.isInteger(v), `case ${i}: ${v}`); assert.ok(x.holdRate === null || (Number.isFinite(x.holdRate) && x.holdRate >= 0 && x.holdRate <= 100)); assert.equal(x.holding + x.regressed, x.provenFixes); assert.equal(x.tier, TIERS.find((t) => x.points >= t.min)?.name ?? "Unranked"); } return N; },
};

test("model equals the real rankFor on every generated history (so the mutants mean something)", () => { const r = prng(SEED); const m = model(); for (let i = 0; i < N; i++) { const h = history(r, 30); assert.deepEqual(strip(m(PRO, h)), strip(rankFor(PRO, h)), `case ${i}`); } });

for (const [name, inv] of Object.entries(INVARIANTS)) {
  test(`invariant ${name}: ${N} seeded histories on the real rankFor`, () => { const n = inv(rankFor); assert.equal(n, N); console.log(`RANKPROP pass ${name} ${n}/${N}`); });
}

// Ties: the public board is a total order, independent of the order pros sit in the store.
function seedBoard(r: R, nPros: number): { jobs: Job[]; pros: { accountId: string; display: string }[] } {
  const jobs: Job[] = []; const pros: { accountId: string; display: string }[] = [];
  for (let p = 0; p < nPros; p++) { const id = `pro_${p}`; pros.push({ accountId: id, display: `Pro ${Math.floor(r() * 3)}` });   // display collides on purpose
    const k = 1 + Math.floor(r() * 3); for (let i = 0; i < k; i++) jobs.push(job(r, { proAccountId: id, severity: "WARN" })); }   // many equal-points pros
  return { jobs, pros };
}
async function board(jobs: Job[], pros: { accountId: string; display: string }[]) {
  const store = new MemoryMarketStore(); for (const j of jobs) await store.putJob(j);
  for (const p of pros) await store.putPro({ accountId: p.accountId, display: p.display, joinedAt: 0, onboarded: true, plan: "payg" });
  return (await leaderboard({ market: { store } } as never)).rows;
}
test(`invariant tiesStable: ${500} seeded boards, row order identical under any store insertion order`, async () => {
  const r = prng(SEED + 10); const M = 500;
  for (let i = 0; i < M; i++) { const { jobs, pros } = seedBoard(r, 3 + Math.floor(r() * 6)); const a = await board(jobs, pros); const b = await board(shuffle(r, jobs), shuffle(r, pros)); assert.deepEqual(b, a, `case ${i}`); assert.equal(JSON.stringify(a).includes("accountId"), false, "no account id leaks to the public board");
    for (let k = 1; k < a.length; k++) assert.ok(a[k - 1].points >= a[k].points, "sorted by points"); }
  console.log(`RANKPROP pass tiesStable ${M}/${M}`);
});
test("boardOrder is a strict total order (antisymmetric, never 0 for distinct accounts)", () => {
  const r = prng(SEED + 11); const rows = Array.from({ length: 200 }, (_, i) => ({ points: Math.floor(r() * 3), provenFixes: Math.floor(r() * 3), display: pick(r, ["A", "B"]), accountId: `a${i}` }));
  for (const x of rows) for (const y of rows) if (x !== y) { assert.notEqual(boardOrder(x, y), 0); assert.equal(Math.sign(boardOrder(x, y)), -Math.sign(boardOrder(y, x))); }
});

// ---- mutants: each must be caught by at least one invariant ----
const MUTANTS: [string, Mut, string][] = [
  ["count unproven jobs", { countUnproven: true }, "noScoreFromUnproven"],
  ["count refunded jobs", { countRefunded: true }, "noScoreFromRefunded"],
  ["ignore wash flag", { ignoreWash: true }, "noScoreFromWash"],
  ["order-dependent", { orderDependent: true }, "orderIndependent"],
  ["allow self-dealt", { allowSelfDealt: true }, "noScoreFromSelfDealt"],
];
for (const [label, mut, killer] of MUTANTS) {
  test(`mutant caught: ${label} (killed by ${killer})`, () => { assert.throws(() => INVARIANTS[killer](model(mut))); assert.doesNotThrow(() => INVARIANTS[killer](model())); console.log(`RANKPROP mutant caught: ${label}`); });
}
test("mutant caught: unstable tie (points-only sort, the pre-f91 board)", async () => {
  const r = prng(SEED + 10); let caught = false;
  const pointsOnly = (x: { points: number }, y: { points: number }) => y.points - x.points;
  for (let i = 0; i < 500 && !caught; i++) { const { jobs, pros } = seedBoard(r, 6); const rank = (ps: typeof pros) => ps.map((p) => ({ ...p, points: rankFor(p.accountId, jobs).points })).sort(pointsOnly).map((p) => p.accountId); if (rank(pros).join() !== rank(shuffle(r, pros)).join()) caught = true; }
  assert.ok(caught, "points-only sort must depend on insertion order"); console.log("RANKPROP mutant caught: unstable tie");
});

// Regressions for the two real defects the suite found (both fixed in f91).
test("regression: one job funded by the pro's own card earns no rank (was ranked until the second repeat)", () => { const r = prng(1); const j = poison(r, "wash_card"); const x = rankFor(PRO, [j]); assert.equal(x.points, 0); assert.equal(x.washExcluded, 1); });
test("regression: a job whose owner IS the pro earns no rank even if the claim guard is bypassed", () => { const r = prng(2); const x = rankFor(PRO, [poison(r, "self_dealt")]); assert.equal(x.points, 0); assert.equal(x.provenFixes, 0); });
